    }

    /// The keys whose values differ from `before`, as "key: old -> new".
    pub fn changes(&self, before: &Settings) -> Vec<String> {
        let (now, was) = (self.to_pairs(), before.to_pairs());
        now.iter()
            .zip(&was)
            .filter(|(n, w)| n.1 != w.1)
            .map(|(n, w)| format!("{}: {} -> {}", n.0, w.1, n.1))
            .collect()
    }
