//! Acceptance tests (PLAN.md A8 step 3, after wipp): the spec a specify turn
//! writes, and what each run of its checks means. The adapter runs the
//! commands; this module decides what their exit codes say.

use serde::{Deserialize, Serialize};

use crate::Event;

/// The checks a specify turn wrote: per criterion, the command that runs
/// only its tests, and the files that hold them.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Spec {
    pub checks: Vec<Check>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Check {
    pub criterion: String,
    pub run: String,
    pub files: Vec<String>,
}

impl Spec {
    /// Every file the checks name, once each, sorted: the approved files.
    pub fn files(&self) -> Vec<String> {
        let mut all: Vec<String> = self.checks.iter().flat_map(|c| c.files.clone()).collect();
        all.sort();
        all.dedup();
        all
    }
}

/// Read a specify turn's reply: one JSON object, fenced or bare.
pub fn spec(report: &str) -> Result<Spec, String> {
    let body = fenced(report).unwrap_or(report);
    let spec: Spec = serde_json::from_str(body.trim())
        .map_err(|e| format!("The reply was not the JSON asked for: {e}."))?;
    if spec.checks.is_empty() {
        return Err("The spec has no checks. Every criterion needs at least one.".into());
    }
    for check in &spec.checks {
        if check.run.trim().is_empty() || check.files.is_empty() {
            return Err(format!(
                "Check {} needs a command and its files.",
                check.criterion
            ));
        }
        if let Some(bad) = check.files.iter().find(|f| !safe_path(f)) {
            return Err(format!(
                "{bad} is not a path inside the repository. Name files relative to it."
            ));
        }
    }
    Ok(spec)
}

/// The text of the first fenced block, if the reply has one.
fn fenced(report: &str) -> Option<&str> {
    let start = report.find("```")?;
    let after = &report[start + 3..];
    let body = &after[after.find('\n')? + 1..];
    Some(&body[..body.find("```")?])
}

/// A path relative to the repository, with no way out of it.
fn safe_path(path: &str) -> bool {
    !path.is_empty()
        && !path.starts_with('/')
        && !path.split('/').any(|part| part == "..")
        && path
            .chars()
            .all(|c| c.is_alphanumeric() || "_./@+-".contains(c))
}

/// One run of one check: its criterion, exit code and the tail of its output.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Ran {
    pub criterion: String,
    pub code: i64,
    pub output: String,
}

impl Ran {
    fn green(&self) -> bool {
        self.code == 0
    }

    /// The shell could not find or run the command at all (wipp's `NOT_RUN`).
    fn not_run(&self) -> bool {
        matches!(self.code, 126 | 127)
    }
}

fn not_run(runs: &[Ran]) -> Vec<String> {
    runs.iter()
        .filter(|r| r.not_run())
        .map(|r| {
            format!(
                "{} did not run (exit {}):\n{}",
                r.criterion, r.code, r.output
            )
        })
        .collect()
}

fn failed_with(problems: Vec<String>) -> Event {
    Event::StepFailed {
        detail: problems.join("\n\n"),
    }
}

/// The baseline, before anything is built: every check must fail. A check
/// that passes already goes to falsify, once per spec.
pub fn baseline(runs: &[Ran], absent: &[String]) -> Event {
    let mut problems = not_run(runs);
    problems.extend(absent.iter().map(|f| format!("{f} is in the spec but not in the tree.")));
    if !problems.is_empty() {
        return failed_with(problems);
    }
    if runs.iter().any(Ran::green) {
        return Event::ChecksGreen;
    }
    Event::StepPassed
}

/// The baseline after falsify: each check ran against the broken code, then
/// against the code put back. A check that passed against the broken code
/// cannot fail, so it checks nothing. A test the falsify turn changed proves
/// nothing either.
pub fn falsified(broken: &[Ran], touched: &[String]) -> Event {
    let mut problems = not_run(broken);
    problems.extend(broken.iter().filter(|r| r.green()).map(|r| {
        format!(
            "{} stayed green when the code was broken on purpose, so it cannot fail and checks nothing.",
            r.criterion
        )
    }));
    problems.extend(
        touched
            .iter()
            .map(|f| format!("The falsify turn changed {f}, which is a test.")),
    );
    if problems.is_empty() {
        Event::StepPassed
    } else {
        failed_with(problems)
    }
}

/// Verify, after the build: every check passes, and no approved file changed
/// since the baseline. A changed test, or one that cannot run, waits on the
/// owner; an unmet criterion goes back to implement.
pub fn verified(runs: &[Ran], changed: &[String]) -> Event {
    if !changed.is_empty() {
        let files: Vec<String> = changed.iter().map(|f| format!("- {f}")).collect();
        return Event::StepStuck {
            detail: format!(
                "The approved checks were changed after the baseline:\n{}\nA passing run of a changed check says nothing about the request.",
                files.join("\n")
            ),
        };
    }
    let cannot = not_run(runs);
    if !cannot.is_empty() {
        return Event::StepStuck {
            detail: format!(
                "The acceptance tests could not run. Make each command runnable in the workspace, then approve to go on.\n\n{}",
                cannot.join("\n\n")
            ),
        };
    }
    let unmet: Vec<String> = runs
        .iter()
        .filter(|r| !r.green())
        .map(|r| {
            format!(
                "{} is not met (exit {}):\n{}",
                r.criterion, r.code, r.output
            )
        })
        .collect();
    if unmet.is_empty() {
        Event::StepPassed
    } else {
        failed_with(unmet)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ran(criterion: &str, code: i64) -> Ran {
        Ran {
            criterion: criterion.into(),
            code,
            output: "out".into(),
        }
    }

    const REPLY: &str = "Here it is.\n```json\n{\"checks\": [\n {\"criterion\": \"C1\", \"run\": \"pytest tests/acceptance -k c1\", \"files\": [\"tests/acceptance/test_c1.py\"]},\n {\"criterion\": \"C2\", \"run\": \"pytest -k c2\", \"files\": [\"tests/acceptance/test_c2.py\", \"tests/acceptance/test_c1.py\"]}\n]}\n```\n";

    #[test]
    fn a_fenced_spec_reads_with_its_files_once_each() {
        let s = spec(REPLY).unwrap();
        assert_eq!(s.checks.len(), 2);
        assert_eq!(
            s.files(),
            ["tests/acceptance/test_c1.py", "tests/acceptance/test_c2.py"]
        );
    }

    #[test]
    fn a_spec_without_a_command_files_or_a_safe_path_is_refused() {
        assert!(spec("no json").is_err());
        assert!(spec(r#"{"checks": []}"#).is_err());
        assert!(spec(r#"{"checks": [{"criterion": "C1", "run": "", "files": ["a"]}]}"#).is_err());
        for bad in ["../etc/passwd", "/tmp/x", "a b"] {
            let reply = format!(r#"{{"checks": [{{"criterion": "C1", "run": "x", "files": ["{bad}"]}}]}}"#);
            assert!(spec(&reply).is_err(), "{bad}");
        }
    }

    #[test]
    fn a_baseline_passes_only_when_every_check_fails() {
        assert_eq!(baseline(&[ran("C1", 1), ran("C2", 2)], &[]), Event::StepPassed);
        assert_eq!(baseline(&[ran("C1", 1), ran("C2", 0)], &[]), Event::ChecksGreen);
        assert!(matches!(
            baseline(&[ran("C1", 127)], &[]),
            Event::StepFailed { detail } if detail.contains("C1 did not run (exit 127)")
        ));
        assert!(matches!(
            baseline(&[ran("C1", 1)], &["t.py".into()]),
            Event::StepFailed { detail } if detail.contains("t.py is in the spec")
        ));
    }

    #[test]
    fn falsify_proves_a_check_only_when_it_goes_red_and_its_test_is_untouched() {
        assert_eq!(falsified(&[ran("C1", 1)], &[]), Event::StepPassed);
        assert!(matches!(
            falsified(&[ran("C1", 0)], &[]),
            Event::StepFailed { detail } if detail.contains("C1 stayed green")
        ));
        assert!(matches!(
            falsified(&[ran("C1", 1)], &["t.py".into()]),
            Event::StepFailed { detail } if detail.contains("changed t.py")
        ));
    }

    #[test]
    fn verify_waits_on_a_changed_test_and_sends_an_unmet_criterion_back() {
        assert_eq!(verified(&[ran("C1", 0)], &[]), Event::StepPassed);
        assert!(matches!(
            verified(&[ran("C1", 0)], &["t.py".into()]),
            Event::StepStuck { detail } if detail.contains("- t.py")
        ));
        assert!(matches!(
            verified(&[ran("C1", 127)], &[]),
            Event::StepStuck { .. }
        ));
        assert!(matches!(
            verified(&[ran("C1", 1)], &[]),
            Event::StepFailed { detail } if detail.contains("C1 is not met (exit 1)")
        ));
    }
}

