//! The acceptance-test steps the factory runs itself (A8 step 3): baseline,
//! verify and acceptance. Each runs the spec's checks in the job's VM, and
//! `bastion_core::acceptance` decides what the exit codes say.

use bastion_core::acceptance::{self, Ran, Spec};
use bastion_core::{Event, Stage};
use serde_json::json;

use super::{BEFORE_TURN, DEFAULT_NAMESPACE, Factory, REPO};
use crate::store::Record;

/// The VM tag on the tree the baseline approved. Verify compares the spec's
/// files against it.
// ponytail: the tag lives in the VM, so a VM rebuilt by revive (A8 step 5) has none.
const SPEC_TAG: &str = "bastion-spec";
/// How long one check may run.
const CHECK_SECS: u64 = 15 * 60;
/// How much of a check's output goes into a brief or a note.
const TAIL: usize = 3000;

impl Factory {
    /// Run baseline, verify or acceptance, and say how it went.
    pub(super) async fn acceptance_step(&self, record: &Record, stage: Stage) -> Event {
        match self.try_acceptance_step(record, stage).await {
            Ok(event) => event,
            Err(detail) => Event::StepStuck { detail },
        }
    }

    async fn try_acceptance_step(&self, record: &Record, stage: Stage) -> Result<Event, String> {
        let vm = record.runtime.sandbox.clone().ok_or("no VM")?;
        let spec = self.latest_spec(&record.job.id).await?;
        let files = spec.files();
        Ok(match stage {
            Stage::Baseline if record.job.falsify_tried => {
                // Judge falsify: the checks against the broken code, then the code put back.
                let broken = self.run_checks(&vm, &spec).await?;
                let touched = self.changed_since(&vm, BEFORE_TURN, &files).await?;
                self.sh(&vm, &format!("git reset -q --hard {BEFORE_TURN} && git clean -qfd"))
                    .await?;
                self.approve_spec(&vm, acceptance::falsified(&broken, &touched))
                    .await?
            }
            Stage::Baseline => {
                self.commit_spec(&vm, &files).await?;
                let absent = self.absent(&vm, &files).await?;
                let runs = self.run_checks(&vm, &spec).await?;
                self.put_back_test_writes(&vm, &files).await?;
                self.approve_spec(&vm, acceptance::baseline(&runs, &absent))
                    .await?
            }
            _ => {
                let changed = self.changed_since(&vm, SPEC_TAG, &files).await?;
                let runs = self.run_checks(&vm, &spec).await?;
                acceptance::verified(&runs, &changed)
            }
        })
    }

    /// The spec the latest specify turn wrote.
    async fn latest_spec(&self, job: &str) -> Result<Spec, String> {
        let artifacts = self.store.artifacts(job).await?;
        let reply = artifacts
            .iter()
            .rev()
            .find(|a| a.stage == Stage::Specify)
            .ok_or("no spec: specify has not run")?;
        acceptance::spec(&reply.body)
    }

    /// A baseline that passes marks the tree its checks were approved on.
    async fn approve_spec(&self, vm: &str, event: Event) -> Result<Event, String> {
        if event == Event::StepPassed {
            self.sh(vm, &format!("git tag -f {SPEC_TAG}")).await?;
        }
        Ok(event)
    }

    /// Commit the spec's files, if the specify turn left them uncommitted, so
    /// they land with the change and a reset to a tag keeps them.
    async fn commit_spec(&self, vm: &str, files: &[String]) -> Result<(), String> {
        let list = quoted(files);
        self.sh(
            vm,
            &format!(
                "git add -- {list} 2>/dev/null; git diff --cached --quiet || git commit -q -m 'Add the acceptance tests'"
            ),
        )
        .await
        .map(|_| ())
    }

    /// The spec's files missing from the tree.
    async fn absent(&self, vm: &str, files: &[String]) -> Result<Vec<String>, String> {
        let list = quoted(files);
        let out = self
            .sh(vm, &format!("for f in {list}; do [ -e \"$f\" ] || echo \"$f\"; done"))
            .await?;
        Ok(lines(&out))
    }

    /// Of the spec's files, those that differ from `tag` in the tree.
    async fn changed_since(&self, vm: &str, tag: &str, files: &[String]) -> Result<Vec<String>, String> {
        let list = quoted(files);
        let out = self
            .sh(vm, &format!("git diff --name-only {tag} -- {list}"))
            .await?;
        Ok(lines(&out))
    }

    /// Files the checks wrote that git tracks and the spec does not name go back.
    // ponytail: untracked files a check leaves stay; wipp puts back tracked files only too.
    async fn put_back_test_writes(&self, vm: &str, files: &[String]) -> Result<(), String> {
        let written = lines(&self.sh(vm, "git diff --name-only").await?);
        let stray: Vec<String> = written.into_iter().filter(|f| !files.contains(f)).collect();
        if !stray.is_empty() {
            self.sh(vm, &format!("git checkout -- {}", quoted(&stray)))
                .await?;
        }
        Ok(())
    }

    async fn run_checks(&self, vm: &str, spec: &Spec) -> Result<Vec<Ran>, String> {
        let mut runs = Vec::new();
        for check in &spec.checks {
            let out = self.exec(vm, &check.run, CHECK_SECS).await?;
            runs.push(Ran {
                criterion: check.criterion.clone(),
                code: out["exit_code"].as_i64().unwrap_or(-1),
                output: tail(&format!(
                    "{}{}",
                    out["stdout"].as_str().unwrap_or_default(),
                    out["stderr"].as_str().unwrap_or_default()
                )),
            });
        }
        Ok(runs)
    }

    /// Run a shell line in the repository, and fail unless it exits 0.
    async fn sh(&self, vm: &str, line: &str) -> Result<String, String> {
        let out = self.exec(vm, line, 120).await?;
        match out["exit_code"].as_i64() {
            Some(0) | None => Ok(out["stdout"].as_str().unwrap_or_default().to_string()),
            Some(code) => Err(format!("{line} exited {code}: {}", out["stderr"])),
        }
    }

    /// Run a shell line in the repository, whatever it exits with.
    async fn exec(&self, vm: &str, line: &str, secs: u64) -> Result<serde_json::Value, String> {
        let argv = ["sh", "-c", &format!("cd {REPO} && {line}")];
        self.engine
            .call_for(
                DEFAULT_NAMESPACE,
                "sandbox::exec",
                json!({ "sandbox_id": vm, "argv": argv, "timeout_ms": secs * 1000 }),
                secs * 1000 + 60_000,
            )
            .await
    }
}

/// Paths as single-quoted shell words. A spec's paths are safe already
/// (`acceptance::spec`), so none holds a quote.
fn quoted(paths: &[String]) -> String {
    let words: Vec<String> = paths.iter().map(|p| format!("'{p}'")).collect();
    words.join(" ")
}

fn lines(out: &str) -> Vec<String> {
    out.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .map(String::from)
        .collect()
}

fn tail(text: &str) -> String {
    let start = text.len().saturating_sub(TAIL);
    let start = (start..=text.len())
        .find(|i| text.is_char_boundary(*i))
        .unwrap_or(text.len());
    text[start..].to_string()
}

